namespace docking.widgets.pathmanager;







public abstract class AbstractTypedPropertyEditor<T> : PropertyEditor {
	private List<PropertyChangeListener> listeners = new();

	private T value = getInitialValue();

	protected T getInitialValue() {
		return null;
